import itertools
from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=float)
def compute_distance(p1, p2):
    return abs(p1 - p2)

@task(returns=float)
def compare_distances(dist1, dist2):
    return min(dist1, dist2)

def main(points):

    distances = []
    for p1, p2 in itertools.combinations(points, 2):
        distance = compute_distance(p1, p2)
        distances.append(distance)

    while len(distances) > 1:
        new_level = []
        for i in range(0, len(distances), 2):
            if i + 1 < len(distances):
                new_level.append(compare_distances(distances[i], distances[i+1]))
            else:
                new_level.append(distances[i])
        distances = new_level


    return compss_wait_on(distances[0])
